export const sriLankaMapRegionById = new Map(
  sriLankaMapRegions.map((region) => [region.id, region]),
);

const MAP_MIN_LON = 79.655772;
const MAP_MAX_LAT = 9.829576;
const MAP_SCALE = 220.1829413010201;
const MAP_OFFSET_X = 53.996425355550514;
const MAP_OFFSET_Y = 20;

export function projectSriLankaPoint(lat: number, lng: number): { x: number; y: number } {
  return {
    x: MAP_OFFSET_X + (lng - MAP_MIN_LON) * MAP_SCALE,
    y: MAP_OFFSET_Y + (MAP_MAX_LAT - lat) * MAP_SCALE,
  };
}
